class Solution {
    public int splitNum(int num){
        char[] digits=String.valueOf(num).toCharArray();
        Arrays.sort(digits);
        int first=0,second=0;
        for(int i=0;i<digits.length;i++){
            if((i&1)==0)first=first*10+digits[i]-'0';
            else second=second*10+digits[i]-'0';
        }
        return first+second;
    }
}

code.kotlin:
class Solution {
    fun splitNum(num:Int):Int{
        val digits=num.toString().map{
            it-'0'
        }.sorted();
        var first=0;
        var second=0;
        for(i in digits.indices)if(i%2==0)first=first*10+digits[i] else second=second*10+digits[i];
        return first+second
    }
}

